        best, out = math.inf, []
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                a, b = sorted((nums[i], nums[j]))
                if b - a < best:
                    best, out = b - a, [[a, b]]
                elif b - a == best:
                    out.append([a, b])
        return sorted(out)

