function closestPairs(nums: number[]): number[][] {
  const a = [...nums].sort((x, y) => x - y);
  let best = Infinity, out: number[][] = [];
  for (let i = 1; i < a.length; i++) {
    const gap = a[i] - a[i - 1];
    if (gap < best) { best = gap; out = []; }
    if (gap === best) out.push([a[i - 1], a[i]]);
  }
  return out;
}

